    private static final int DEFAULT_TIMEOUT_MILLIS = 10000;
    private static final int READ_BUFFER_SIZE = 8192;

    public static void main(String[] args) {
        String host = args.length > 0 ? args[0] : DEFAULT_HOST;
        int port = args.length > 1 ? Integer.parseInt(args[1]) : DEFAULT_PORT;
        String request = args.length > 2 ? args[2] : null;
        int timeout = args.length > 3 ? Integer.parseInt(args[3]) : DEFAULT_TIMEOUT_MILLIS;
        try {
            String result = performSecureRequest(host, port, request, timeout);
            System.out.println(result);
        } catch (Exception ex) {
            System.err.println("Secure connection failed: " + ex.getClass().getName() + ": " + ex.getMessage());
        }
    }

    public static String performSecureRequest(String host, int port, String request, int timeoutMillis) throws IOException {
        SSLSocket socket = null;
        try {
            socket = createSecureSocket(host, port, timeoutMillis);
            socket.startHandshake();
            String connectionInfo = describeConnection(socket);
            if (request == null || request.isEmpty()) {
                return connectionInfo;
            }
            int bytesWritten = writeRequest(socket, request, timeoutMillis);
            String response = readResponse(socket, timeoutMillis);
            return connectionInfo + System.lineSeparator() + "Request bytes sent: " + bytesWritten + System.lineSeparator() + response;
        } finally {
            closeQuietly(socket);
        }
    }

    public static SSLSocket createSecureSocket(String host, int port, int timeoutMillis) throws IOException {
        SSLContext context = SSLContext.getInstance("TLS");
        context.init(null, null, null);
        SSLSocketFactory factory = context.getSocketFactory();
        SSLSocket socket = (SSLSocket) factory.createSocket();
        socket.setSoTimeout(timeoutMillis);
        socket.setUseClientMode(true);
        socket.setNeedClientAuth(false);
        socket.setWantClientAuth(false);
        socket.setEnableSessionCreation(true);
        configureSocket(socket);
        socket.connect(new InetSocketAddress(host, port), timeoutMillis);
        return socket;
    }

    public static SSLSocket configureSocket(SSLSocket socket) throws IOException {
        String[] secureProtocols = selectSecureProtocols(socket);
        socket.setEnabledProtocols(secureProtocols);
        SSLParameters parameters = socket.getSSLParameters();
        parameters.setEndpointIdentificationAlgorithm("HTTPS");
        socket.setSSLParameters(parameters);
        return socket;
    }

    public static String[] selectSecureProtocols(SSLSocket socket) throws SSLException {
        String[] supported = socket.getSupportedProtocols();
        String[] selected = new String[0];
        for (String protocol : supported) {
            if ("TLSv1.2".equals(protocol) || "TLSv1.3".equals(protocol)) {
                String[] expanded = new String[selected.length + 1];
                System.arraycopy(selected, 0, expanded, 0, selected.length);
                expanded[selected.length] = protocol;
                selected = expanded;
            }
        }
        if (selected.length == 0) {
            throw new SSLException("No secure TLS protocol available (TLSv1.2 or TLSv1.3 required)");
        }
        return selected;
    }

    public static int writeRequest(SSLSocket socket, String request, int timeoutMillis) throws IOException {
        OutputStream out = socket.getOutputStream();
        byte[] payload = request.getBytes(StandardCharsets.UTF_8);
        out.write(payload);
        out.flush();
        return payload.length;
    }

    public static String readResponse(SSLSocket socket, int timeoutMillis) throws IOException {
        InputStream in = socket.getInputStream();
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        byte[] chunk = new byte[READ_BUFFER_SIZE];
        try {
            int read;
            while ((read = in.read(chunk)) != -1) {
                buffer.write(chunk, 0, read);
            }
        } catch (SocketTimeoutException timeout) {
            // Return whatever was received before the timeout.
        }
        return new String(buffer.toByteArray(), StandardCharsets.UTF_8);
    }

    public static String describeConnection(SSLSocket socket) {
        SSLSession session = socket.getSession();
        String peer = socket.getRemoteSocketAddress() == null ? "unknown" : socket.getRemoteSocketAddress().toString();
        return "Secure TLS connection established" + System.lineSeparator()
            + "Peer: " + peer + System.lineSeparator()
            + "Protocol: " + session.getProtocol() + System.lineSeparator()
            + "Cipher suite: " + session.getCipherSuite() + System.lineSeparator()
            + "Peer principal: " + String.valueOf(session.getPeerPrincipal()) + System.lineSeparator()
            + "Local principal: " + String.valueOf(session.getLocalPrincipal());
    }

    public static boolean closeQuietly(SSLSocket socket) {
        if (socket == null) return false;
        try { socket.close(); return true; } catch (IOException ignored) { return false; }
    }
